/**
 * components/LoadingSpinner.js
 * Neural-ring spinner with step-by-step pipeline progress
 */

import React, { useState, useEffect, useRef } from 'react';
import './LoadingSpinner.css';

const STEPS = [
  'Fetching market data',
  'Running LSTM + Attention',
  'Computing SHAP values',
  'Extracting attention weights',
  'Detecting market regime',
];

export default function LoadingSpinner({ active }) {
  const [step, setStep] = useState(0);
  const timer = useRef(null);

  useEffect(() => {
    if (!active) { setStep(0); clearInterval(timer.current); return; }
    setStep(0);
    let i = 0;
    timer.current = setInterval(() => {
      i++;
      if (i >= STEPS.length) clearInterval(timer.current);
      else setStep(i);
    }, 950);
    return () => clearInterval(timer.current);
  }, [active]);

  if (!active) return null;

  return (
    <div className="loading-panel">
      <div className="neural-spin">
        <div className="ns-r r1" />
        <div className="ns-r r2" />
        <div className="ns-r r3" />
      </div>
      <div className="load-title">NEURAL NETWORK PROCESSING</div>
      <div className="load-steps">
        {STEPS.map((s, i) => (
          <div
            key={i}
            className={`ls ${step === i ? 'active' : step > i ? 'done' : ''}`}
          >
            {step > i ? '✓ ' : ''}{s}
          </div>
        ))}
      </div>
      <div className="load-note">
        SHAP computation may take 15–30 seconds on first run
      </div>
    </div>
  );
}
